import type { MappedFlow } from '../planning/target-flows.js';
import { mermaidLabel } from './mermaid-label.js';

// RF-625, RF-508, DEC-134: the Mermaid sequence diagram of a target flow, generated by code from
// the checked flow; the model never writes Mermaid. What starts the journey is an actor named for
// it (`triggerActor`), with the trigger sentence in a note over it. Every legacy step is drawn, in
// order and numbered: a step mapped to a component is a message from the previous participant to
// that component; a step mapped to none is drawn on the nearest mapped component (the previous
// step's, else the next one's, else a participant "Legacy step") and marked "(not mapped)"; a step the code placed from the files it cites, not the planner, is marked "(inferred)", so no
// number is skipped. Participant ids are generated (`p1`, `p2`, ...), never taken from names;
// `mask` hides secrets in every label before `mermaidLabel` codes it.

const unmappedMark = ' (not mapped)';
const inferredMark = ' (inferred)';
const noComponent = 'Legacy step';

const actors: readonly (readonly [RegExp, string])[] = [
  [/\b(?:schedul\w*|timer|cron|nightly|daily|hourly|weekly|periodic\w*)\b/iu, 'Scheduler'],
  [/\b(?:message|queue|event|webhook|callback|notification)\b/iu, 'Message sender'],
  [/\b(?:http|https|request|browser|client|api|url|endpoint|web)\b/iu, 'Client'],
  [/\b(?:user|customer|staff|admin\w*|operator|employee|clerk|visitor|person|buyer)\b/iu, 'User'],
];

/** A short name, at most 40 characters, for who or what starts a flow, from its trigger. */
// RF-625
export function triggerActor(trigger: string): string {
  return actors.find(([pattern]) => pattern.test(trigger))?.[1] ?? 'Trigger';
}

/** The component each step is drawn on: its own, else the previous one's, else the next one's. */
function drawnOn(flow: MappedFlow): (string | null)[] {
  const own = flow.steps.map((step) => step.component);
  return own.map((component, index) => {
    if (component !== null) return component;
    const before = own.slice(0, index).findLast((each) => each !== null);
    return before ?? own.slice(index).find((each) => each !== null) ?? null;
  });
}

// RF-625
export function targetFlowDiagram(flow: MappedFlow, mask: (text: string) => string): string {
  const label = (text: string): string => mermaidLabel(mask(text));
  const ids = new Map<string, string>();
  const lines: string[] = [];
  const participant = (key: string, name: string, kind = 'participant'): string => {
    const known = ids.get(key);
    if (known !== undefined) return known;
    const id = `p${String(ids.size + 1)}`;
    ids.set(key, id);
    lines.push(`  ${kind} ${id} as ${label(name)}`);
    return id;
  };
  // Keys carry a prefix, so no component name can be taken for the trigger.
  const trigger = participant('trigger', triggerActor(flow.trigger), 'actor');
  const messages = flow.trigger === '' ? [] : [`  Note over ${trigger}: ${label(flow.trigger)}`];
  let at = trigger;
  const places = drawnOn(flow);
  flow.steps.forEach((step, index) => {
    const name = places[index] ?? noComponent;
    const to = participant(`component ${name}`, name);
    const text = step.component !== null && step.action !== '' ? step.action : step.text;
    const mark = step.component === null ? unmappedMark : step.inferred ? inferredMark : '';
    messages.push(`  ${at}->>${to}: ${label(`${String(index + 1)}. ${text}${mark}`)}`);
    at = to;
  });
  if (flow.outcome !== '') messages.push(`  Note over ${at}: ${label(`Outcome: ${flow.outcome}`)}`);
  return ['sequenceDiagram', ...lines, ...messages, ''].join('\n');
}
